// Time‑unit constants expressed in milliseconds.

const s = 1e3;          // seconds
const m = s * 60;       // minutes
const h = m * 60;       // hours
const d = h * 24;       // days
const w = d * 7;        // weeks
const y = d * 365.25;   // years (average, accounting for leap years)

// Export the constants for CommonJS environments.
