/**
 * Exported utility function.
 *
 * - If `val` is a non‑empty string, it is parsed with the `parse` helper.
 * - If `val` is a finite number, it is formatted with either `fmtLong` or
 *   `fmtShort` depending on the `long` flag in `options`.
 * - For any other input an error is thrown.
 *
 * The helpers `parse`, `fmtLong` and `fmtShort` are expected to be defined
 * elsewhere in the bundle and are used as‑is.
 */
function exported(val, options) {
  // Ensure we always have an options object.
  options = options || {};

  const type = typeof val;

  // Handle string input.
  if (type === 'string' && val.length > 0) {
    return parse(val);
  }

  // Handle numeric input.
  if (type === 'number' && Number.isFinite(val)) {
    return options.long ? fmtLong(val) : fmtShort(val);
  }

  // Anything else is invalid.
  throw new Error(
    'val is not a non-empty string or a valid number. val=' + JSON.stringify(val)
  );
}

