const m = MILLISECONDS_IN_MINUTE;
const h = MILLISECONDS_IN_HOUR;
const d = MILLISECONDS_IN_DAY;
const w = MILLISECONDS_IN_WEEK;
const y = MILLISECONDS_IN_YEAR;

/**
 * Parse a human‑readable duration string and return the length in milliseconds.
 *
 * Supported formats (case‑insensitive):
 *   "<number> ms|msec|milliseconds"
 *   "<number> s|sec|secs|seconds"
 *   "<number> m|min|mins|minutes"
 *   "<number> h|hr|hrs|hours"
 *   "<number> d|day|days"
 *   "<number> w|week|weeks"
 *   "<number> y|yr|yrs|year|years"
 *
 * The numeric part may be an integer or a decimal, optionally prefixed with `-`.
 * Strings longer than 100 characters are rejected (returns `undefined`).
 *
 * @param {any} str - The value to parse.
 * @returns {number|undefined} Milliseconds, or `undefined` if parsing fails.
 */
function parse(str) {
  // Coerce to string – this mirrors the original behaviour.
  str = String(str);

  // Guard against excessively long inputs (original limit).
  if (str.length > 100) {
    return;
  }

  // Regex captures:
  //   1) the numeric value (with optional sign and decimal point)
  //   2) an optional unit suffix
  const match = /^(-?(?:\d+)?\.?\d+) *(milliseconds?|msecs?|ms|seconds?|secs?|s|minutes?|mins?|m|hours?|hrs?|h|days?|d|weeks?|w|years?|yrs?|y)?$/i.exec(
    str
  );

  if (!match) {
    return;
  }

  const n = parseFloat(match[1]);               // numeric magnitude
  const type = (match[2] || "ms").toLowerCase(); // default to milliseconds

  switch (type) {
    case "years":
    case "year":
    case "yrs":
    case "yr":
    case "y":
      return n * y;

    case "weeks":
    case "week":
    case "w":
      return n * w;

    case "days":
    case "day":
    case "d":
      return n * d;

    case "hours":
    case "hour":
    case "hrs":
    case "hr":
    case "h":
      return n * h;

    case "minutes":
    case "minute":
    case "mins":
    case "min":
    case "m":
      return n * m;

    case "seconds":
    case "second":
    case "secs":
    case "sec":
    case "s":
      return n * s;

    case "milliseconds":
    case "millisecond":
    case "msecs":
    case "msec":
    case "ms":
      return n;

    default:
      // Should never happen because the regex restricts the suffix,
      // but we keep the original fallback.
      return undefined;
  }
