// Time unit constants (milliseconds)
const DAY_MS   = 24 * 60 * 60 * 1000; // 86 400 000 ms
const HOUR_MS  = 60 * 60 * 1000;      // 3 600 000 ms
const MINUTE_MS = 60 * 1000;         // 60 000 ms
const SECOND_MS = 1000;              // 1 000 ms

/**
 * Formats a duration given in milliseconds to a short human‑readable string.
 *
 * The function picks the largest time unit for which the absolute value of the
 * duration is at least one whole unit, rounds to the nearest integer, and
 * appends the appropriate suffix:
 *   - "d" for days
 *   - "h" for hours
 *   - "m" for minutes
 *   - "s" for seconds
 *   - "ms" for milliseconds (fallback)
 *
 * @param {number} ms – Duration in milliseconds (can be negative).
 * @returns {string} Short formatted duration.
 */
function fmtShort(ms) {
  const msAbs = Math.abs(ms);

  if (msAbs >= DAY_MS) {
    return Math.round(ms / DAY_MS) + "d";
  }
  if (msAbs >= HOUR_MS) {
    return Math.round(ms / HOUR_MS) + "h";
  }
  if (msAbs >= MINUTE_MS) {
    return Math.round(ms / MINUTE_MS) + "m";
  }
  if (msAbs >= SECOND_MS) {
    return Math.round(ms / SECOND_MS) + "s";
  }
  return ms + "ms";
}

