 * Convert a duration expressed in milliseconds to a human‑readable string.
 * The function picks the *largest* unit that fits into the absolute value of
 * the input and formats the value with proper pluralisation.
 *
 * @param {number} ms – duration in milliseconds (may be negative)
 * @returns {string}
 */
function fmtLong(ms) {
  const msAbs = Math.abs(ms);

  if (msAbs >= d) {
    return plural(ms, msAbs, d, "day");
  }
  if (msAbs >= h) {
    return plural(ms, msAbs, h, "hour");
  }
  if (msAbs >= m) {
    return plural(ms, msAbs, m, "minute");
  }
  if (msAbs >= s) {
    return plural(ms, msAbs, s, "second");
  }
  return ms + " ms";
}

/**
 * Helper that formats a value in a given unit, handling pluralisation and
 * preserving the sign of the original millisecond value.
 *
 * @param {number} originalMs – the original value passed to fmtLong
 * @param {number} _absMs     – absolute value of originalMs (pre‑computed, kept
 *                              for signature compatibility)
 * @param {number} unitMs     – number of milliseconds in the unit
 * @param {string} unitName   – singular name of the unit (e.g. "day")
 * @returns {string}
 */
function plural(originalMs, _absMs, unitMs, unitName) {
  // The integer amount of the chosen unit.  Using Math.trunc keeps the sign
  // and discards any fractional part (e.g. 1.9 days → 1 day).
  const amount = Math.trunc(originalMs / unitMs);
  const suffix = Math.abs(amount) === 1 ? "" : "s";
  return amount + " " + unitName + suffix;
}

// -----------------------------------------------------------------------------
// Export for CommonJS / ES‑module consumers (optional, harmless if unused)
// -----------------------------------------------------------------------------
if (typeof module !== "undefined" && module.exports) {
  module.exports = fmtLong;
}

/**
 * Formats a numeric value with the appropriate singular or plural unit name.
 *
 * @param {number} ms      - The original value (e.g., a duration in milliseconds).
 * @param {number} msAbs   - The absolute value of the original quantity.
 * @param {number} n       - The divisor used to scale the value (e.g., 1000 for seconds).
 * @param {string} name    - The base unit name (e.g., "second").
 * @returns {string} A string containing the rounded value and the correctly
 *                   pluralized unit name.
 */
function plural(ms, msAbs, n, name) {
  const isPlural = msAbs >= n * 1.5;
  return Math.round(ms / n) + " " + name + (isPlural ? "s" : "");
}

